package org.marketreview.nativeapp;
import org.json.*;
import java.nio.charset.StandardCharsets;
import java.security.MessageDigest;
import java.time.Instant;
import java.util.*;

/** Human labels and old equal-mean/trend rules, never official leaders or an index. */
final class SectorLeaderModel {
 static final String SCHEMA="native-sector-leaders/v1",SHOT="native-sector-leader-observation/v1";
 static final String[] ROLES={"总龙头","趋势龙头","容量龙头","补涨龙头","观察股"};
 static final int MAX=2*1024*1024;
 static String time(Instant at){return new java.time.format.DateTimeFormatterBuilder().appendInstant(3).toFormatter().format(at);}
 static void need(boolean b,String s){if(!b)throw new IllegalArgumentException(s);}
 static void active(java.util.function.BooleanSupplier cancel){need(!Thread.currentThread().isInterrupted()&&(cancel==null||!cancel.getAsBoolean()),"人工观察操作已取消");}
 static String hash(byte[] bytes)throws Exception{StringBuilder b=new StringBuilder();for(byte x:MessageDigest.getInstance("SHA-256").digest(bytes))b.append(String.format(Locale.ROOT,"%02x",x&255));return b.toString();}
 static String bounded(JSONObject o,String key,int max,boolean required){Object v=o.opt(key);need(v==null||v==JSONObject.NULL||v instanceof String,"文本字段类型错误："+key);String s=v instanceof String?(String)v:"";need(s.length()<=max&&(!required||!s.trim().isEmpty()),"文本字段为空或过长："+key);return s;}
 static Object finite(Object v){if(!(v instanceof Number))return JSONObject.NULL;double n=((Number)v).doubleValue();return Double.isFinite(n)?n:JSONObject.NULL;}
 static Double value(Object v){Object n=finite(v);return n instanceof Number?((Number)n).doubleValue():null;}
 // Match old JS Number(n.toFixed(2)): round the binary double, not a decimal approximation.
 static double round2(double n){return new java.math.BigDecimal(n).setScale(2,java.math.RoundingMode.HALF_UP).doubleValue();}
 static Object observed(JSONObject quote,String key){Object n=finite(quote.opt(key.equals("change")?"changePercent":key));if(!(n instanceof Number))return JSONObject.NULL;double value=((Number)n).doubleValue();if(key.equals("price")&&value<=0||key.equals("amount")&&value<0)return JSONObject.NULL;return key.equals("change")?finite(round2(value)):n;}
 static String identity(String fullId,String code){need(code.matches("[0-9]{6}"),"候选代码须为6位");if(fullId==null||fullId.isEmpty())return "unresolved";need(fullId.matches("(SH|SZ|BJ):stock:[0-9]{6}")&&fullId.endsWith(":"+code),"完整证券身份与代码不符");String market=fullId.substring(0,2);need(market.equals("SH")&&code.matches("(60|68|90)[0-9]{4}")||market.equals("SZ")&&code.matches("(00|20|30)[0-9]{4}")||market.equals("BJ")&&code.matches("(4[0-9]|8[0-9]|92)[0-9]{4}"),"当前仅支持明确市场的普通股票");return "confirmed-user";}
 static JSONObject empty()throws JSONException{return new JSONObject().put("schema",SCHEMA).put("revision",0).put("updatedAt",JSONObject.NULL).put("sectors",new JSONArray());}
 static JSONObject newBoard(String name)throws JSONException{return new JSONObject().put("id",UUID.randomUUID().toString()).put("name",name.trim()).put("description","").put("sortOrder",0).put("leaders",new JSONArray());}
 static JSONObject newLeader(String boardId,String code,String name,String fullId)throws JSONException{return new JSONObject().put("id",UUID.randomUUID().toString()).put("sectorId",boardId).put("code",code).put("name",name.trim()).put("fullId",fullId==null||fullId.isEmpty()?JSONObject.NULL:fullId).put("identityState",identity(fullId,code)).put("role","观察股").put("reason","").put("weight",1).put("note","");}
 static void validate(JSONObject c)throws JSONException{
  need(SCHEMA.equals(c.optString("schema"))&&value(c.opt("revision"))!=null&&c.getDouble("revision")>=0&&c.getDouble("revision")<=9007199254740991.&&c.getDouble("revision")==Math.floor(c.getDouble("revision")),"人工配置格式/版本错误");JSONArray boards=c.getJSONArray("sectors");need(boards.length()<=100,"人工板块最多100项");Set<String> ids=new HashSet<>(),names=new HashSet<>();int total=0;
  for(int i=0;i<boards.length();i++){JSONObject b=boards.getJSONObject(i);need(ids.add(bounded(b,"id",128,true))&&names.add(bounded(b,"name",120,true).trim()),"板块id/名称重复");bounded(b,"description",4000,false);need(value(b.opt("sortOrder"))!=null&&Math.abs(b.getDouble("sortOrder"))<=1000000,"板块排序须有限数字");JSONArray rows=b.getJSONArray("leaders");total+=rows.length();need(total<=1000,"人工候选总数最多1000项");Set<String> identities=new HashSet<>();
   for(int j=0;j<rows.length();j++){JSONObject r=rows.getJSONObject(j);need(ids.add(bounded(r,"id",128,true))&&b.getString("id").equals(r.optString("sectorId")),"候选id或板块归属重复/错误");String code=bounded(r,"code",6,true),full=bounded(r,"fullId",32,false);need(identity(full,code).equals(r.optString("identityState")),"身份核对状态错误");bounded(r,"name",160,true);need(Arrays.asList(ROLES).contains(r.optString("role")),"角色必须明确选择人工标签");bounded(r,"reason",4000,false);bounded(r,"note",4000,false);need(value(r.opt("weight"))!=null&&Math.abs(r.getDouble("weight"))<=1000000,"人工权重须有限数字");need(identities.add((full.isEmpty()?"unresolved:"+code:full)+"|"+r.optString("role")),"同板块同身份与角色重复");}
  }need(c.toString().getBytes(StandardCharsets.UTF_8).length<=MAX,"人工配置超过2MiB");
 }
 static JSONObject board(JSONObject c,String id)throws JSONException{for(int i=0;i<c.getJSONArray("sectors").length();i++){JSONObject b=c.getJSONArray("sectors").getJSONObject(i);if(b.getString("id").equals(id))return b;}throw new IllegalArgumentException("人工板块不存在");}
 static JSONObject normalize(JSONObject input)throws Exception{
  if(SCHEMA.equals(input.optString("schema"))){validate(input);return new JSONObject(input.toString());}need(input.optInt("version",-1)==1&&input.optJSONArray("sectors")!=null,"仅接受旧version1人工配置或原生完整备份");JSONObject c=empty();JSONArray out=c.getJSONArray("sectors"),source=input.getJSONArray("sectors");need(source.length()<=100,"板块超上限");
  for(int i=0;i<source.length();i++){JSONObject raw=source.getJSONObject(i);String name=bounded(raw,"name",120,true).trim(),id="legacy-board-"+hash(name.getBytes(StandardCharsets.UTF_8));JSONObject b=newBoard(name).put("id",id).put("description",bounded(raw,"description",4000,false)).put("sortOrder",raw.has("sortOrder")?raw.get("sortOrder"):0);JSONArray leaders=raw.optJSONArray("leaders");need(!raw.has("leaders")||leaders!=null,"旧候选列表格式错误");if(leaders!=null)for(int j=0;j<leaders.length();j++){JSONObject r=leaders.getJSONObject(j);String code=bounded(r,"code",6,true),full=bounded(r,"fullId",32,false),role=r.optString("role","观察股");JSONObject l=newLeader(id,code,r.optString("name",code),full).put("id","legacy-leader-"+hash((name+"|"+(full.isEmpty()?code:full)+"|"+role).getBytes(StandardCharsets.UTF_8))).put("role",role).put("reason",bounded(r,"reason",4000,false)).put("note",bounded(r,"note",4000,false)).put("weight",r.has("weight")?r.get("weight"):1);b.getJSONArray("leaders").put(l);}out.put(b);}validate(c);return c;
 }
 static JSONObject preview(byte[] bytes,JSONObject current)throws Exception{
  need(bytes!=null&&bytes.length>0&&bytes.length<=MAX,"导入文件须为不超过2MiB的JSON");validate(current);JSONObject incoming=normalize(new JSONObject(new String(bytes,StandardCharsets.UTF_8))),merged=new JSONObject(current.toString());JSONArray conflicts=new JSONArray();int addedBoards=0,addedLeaders=0,unresolved=0;Set<String> global=new HashSet<>();for(int i=0;i<merged.getJSONArray("sectors").length();i++){JSONObject b=merged.getJSONArray("sectors").getJSONObject(i);global.add(b.getString("id"));for(int j=0;j<b.getJSONArray("leaders").length();j++)global.add(b.getJSONArray("leaders").getJSONObject(j).getString("id"));}
  for(int i=0;i<incoming.getJSONArray("sectors").length();i++){JSONObject b=incoming.getJSONArray("sectors").getJSONObject(i),target=null;for(int j=0;j<merged.getJSONArray("sectors").length();j++){JSONObject old=merged.getJSONArray("sectors").getJSONObject(j);if(old.getString("name").equals(b.getString("name"))){target=old;break;}}if(target==null){need(!global.contains(b.getString("id")),"导入板块id冲突");target=new JSONObject(b.toString()).put("leaders",new JSONArray());merged.getJSONArray("sectors").put(target);global.add(target.getString("id"));addedBoards++;}else conflicts.put("保留既有板块字段："+target.getString("name"));
   for(int j=0;j<b.getJSONArray("leaders").length();j++){JSONObject l=new JSONObject(b.getJSONArray("leaders").getJSONObject(j).toString());boolean duplicate=global.contains(l.getString("id"));for(int k=0;k<target.getJSONArray("leaders").length();k++){JSONObject old=target.getJSONArray("leaders").getJSONObject(k);if(old.optString("fullId").equals(l.optString("fullId"))&&old.getString("code").equals(l.getString("code"))&&old.getString("role").equals(l.getString("role")))duplicate=true;}if(duplicate){conflicts.put("跳过已有候选，不覆盖人工稿："+l.getString("name"));continue;}l.put("sectorId",target.getString("id"));target.getJSONArray("leaders").put(l);global.add(l.getString("id"));addedLeaders++;if(l.isNull("fullId"))unresolved++;}
  }validate(merged);return new JSONObject().put("digest",hash(bytes)).put("expectedRevision",current.getLong("revision")).put("config",merged).put("addedBoards",addedBoards).put("addedLeaders",addedLeaders).put("unresolvedCount",unresolved).put("conflicts",conflicts);
 }
 static String strength(Double change){return change==null?"未知":change>=3?"强":change<=-3?"弱":"平";}
 static JSONObject summary(JSONArray rows)throws JSONException{double sum=0;int valid=0,cached=0;for(int i=0;i<rows.length();i++){JSONObject r=rows.getJSONObject(i);Double change=value(r.opt("change"));if(change!=null){sum+=change;valid++;}if(r.optJSONObject("quote")!=null&&r.getJSONObject("quote").optBoolean("cached"))cached++;}Double mean=valid==0||!Double.isFinite(sum)?null:sum/valid;return new JSONObject().put("avgChange",mean==null?JSONObject.NULL:round2(mean)).put("validCount",valid).put("memberCount",rows.length()).put("cachedCount",cached).put("status",mean==null?"待刷新":mean>=1?"偏强":mean<=-1?"偏弱":"震荡");}
 static JSONObject freeze(JSONObject c,String sectorId,JSONObject quotes,Instant at)throws Exception{
  validate(c);JSONObject b=board(c,sectorId);JSONArray rows=new JSONArray();for(int i=0;i<b.getJSONArray("leaders").length();i++){JSONObject r=new JSONObject(b.getJSONArray("leaders").getJSONObject(i).toString()),q=quotes.optJSONObject(r.optString("fullId"));if(q==null)q=new JSONObject();q=new JSONObject(q.toString());Object price=finite(q.opt("price")),change=finite(q.opt("changePercent")),amount=finite(q.opt("amount"));if(change instanceof Number)change=finite(round2(((Number)change).doubleValue()));if(price instanceof Number&&((Number)price).doubleValue()<=0)price=JSONObject.NULL;if(amount instanceof Number&&((Number)amount).doubleValue()<0)amount=JSONObject.NULL;r.put("quote",q).put("price",price).put("change",change).put("amount",amount).put("strength",strength(value(change)));rows.put(r);}
  JSONObject s=new JSONObject().put("schema",SHOT).put("id",UUID.randomUUID().toString()).put("sectorId",sectorId).put("sectorName",b.getString("name")).put("configRevision",c.getLong("revision")).put("capturedAt",time(at)).put("manualBoard",new JSONObject(b.toString())).put("rows",rows).put("summary",summary(rows));validateShot(s);return s;
 }
 static void validateShot(JSONObject s)throws Exception{need(SHOT.equals(s.optString("schema")),"观察快照格式错误");bounded(s,"id",128,true);Instant.parse(s.getString("capturedAt"));JSONObject c=empty().put("revision",s.get("configRevision")).put("sectors",new JSONArray().put(s.getJSONObject("manualBoard")));validate(c);need(s.getString("sectorId").equals(s.getJSONObject("manualBoard").getString("id"))&&s.getString("sectorName").equals(s.getJSONObject("manualBoard").getString("name")),"快照板块身份不符");JSONArray rows=s.getJSONArray("rows"),manual=s.getJSONObject("manualBoard").getJSONArray("leaders");need(rows.length()==manual.length(),"快照成员不完整");for(int i=0;i<rows.length();i++){JSONObject r=rows.getJSONObject(i),l=manual.getJSONObject(i);Iterator<String> keys=l.keys();while(keys.hasNext()){String k=keys.next();need(equal(r.opt(k),l.opt(k)),"快照人工字段被改写");}need(r.optJSONObject("quote")!=null,"快照报价须为对象");for(String k:new String[]{"price","change","amount"}){need(r.has(k)&&(r.isNull(k)||value(r.opt(k))!=null),"快照缺数格式错误");need(equal(r.opt(k),observed(r.getJSONObject("quote"),k)),"快照数字与原报价不符");}need(strength(value(r.opt("change"))).equals(r.optString("strength")),"强弱公式不符");}need(equal(s.opt("summary"),summary(rows)),"快照均值与覆盖错误");need(s.toString().getBytes(StandardCharsets.UTF_8).length<=4*MAX,"观察快照过大");}
 static boolean equal(Object a,Object b)throws JSONException{if(a instanceof Number&&b instanceof Number)return Double.compare(((Number)a).doubleValue(),((Number)b).doubleValue())==0;if(a instanceof JSONObject&&b instanceof JSONObject){JSONObject x=(JSONObject)a,y=(JSONObject)b;if(x.length()!=y.length())return false;Iterator<String> keys=x.keys();while(keys.hasNext()){String k=keys.next();if(!y.has(k)||!equal(x.get(k),y.get(k)))return false;}return true;}if(a instanceof JSONArray&&b instanceof JSONArray){JSONArray x=(JSONArray)a,y=(JSONArray)b;if(x.length()!=y.length())return false;for(int i=0;i<x.length();i++)if(!equal(x.get(i),y.get(i)))return false;return true;}return Objects.equals(a,b);}
 static JSONObject trend(JSONArray history,String leaderId,String fullId)throws JSONException{Double latest=null,previous=null;String latestAt="";int samples=0;for(int i=0;i<history.length();i++){JSONObject s=history.getJSONObject(i);JSONArray rows=s.getJSONArray("rows");for(int j=0;j<rows.length();j++){JSONObject r=rows.getJSONObject(j);if(!r.getString("id").equals(leaderId)||!r.optString("fullId").equals(fullId))continue;Double change=value(r.opt("change"));if(samples++==0){latest=change;latestAt=s.optString("capturedAt");}else if(previous==null&&change!=null)previous=change;}}Double delta=latest==null||previous==null?null:round2(latest-previous);return new JSONObject().put("latestChange",latest==null?JSONObject.NULL:latest).put("previousChange",previous==null?JSONObject.NULL:previous).put("changeDelta",delta==null?JSONObject.NULL:delta).put("samples",samples).put("latestAt",latestAt);}
 static String cell(Object v){String s=v==null||v==JSONObject.NULL?"":v.toString();if(!s.isEmpty()&&"=+-@\t\r\n".indexOf(s.charAt(0))>=0)s="'"+s;return "\""+s.replace("\"","\"\"")+"\"";}
 static byte[] csv(JSONObject s)throws Exception{validateShot(s);StringBuilder out=new StringBuilder("\uFEFFcapturedAt,sectorName,fullId,code,name,role,reason,weight,note,price,change,amount,source,tradeDate,tradeTime,checkedAt,cached,error\r\n");for(int i=0;i<s.getJSONArray("rows").length();i++){JSONObject r=s.getJSONArray("rows").getJSONObject(i),q=r.getJSONObject("quote");List<String> cells=new ArrayList<>();cells.add(cell(s.get("capturedAt")));cells.add(cell(s.get("sectorName")));for(String k:new String[]{"fullId","code","name","role","reason","weight","note","price","change","amount"})cells.add(cell(r.opt(k)));for(String k:new String[]{"source","tradeDate","tradeTime","checkedAt","cached","error"})cells.add(cell(q.opt(k)));out.append(String.join(",",cells)).append("\r\n");}return out.toString().getBytes(StandardCharsets.UTF_8);}
 static JSONObject instrument(JSONObject row)throws JSONException{String id=row.optString("fullId");need(!identity(id,row.getString("code")).equals("unresolved"),"来源身份待核，不能联动");String[] p=id.split(":");return new JSONObject().put("id",id).put("code",p[2]).put("symbol",p[0].toLowerCase(Locale.ROOT)+p[2]).put("market",p[0]).put("type","stock").put("name",row.getString("name")).put("group","默认分组");}
}
